<template><div class="app-container"><el-alert title="此页只查看授权关系，不提供绕过用户授权的健康明细入口。" type="warning" :closable="false" style="margin-bottom:16px"/><div class="filter-container"><el-input v-model="query.ownerUserId" placeholder="数据所有人ID" style="width:160px"/><el-input v-model="query.granteeUserId" placeholder="健康顾问ID" style="width:160px"/><el-select v-model="query.status" clearable placeholder="状态"><el-option label="有效" value="ACTIVE"/><el-option label="已撤销" value="REVOKED"/></el-select><el-button type="primary" @click="load">查询</el-button></div><el-table v-loading="loading" :data="list" border><el-table-column prop="authorizationNo" label="授权编号" min-width="180"/><el-table-column prop="ownerName" label="用户"/><el-table-column prop="granteeName" label="健康顾问"/><el-table-column prop="scopeCodes" label="授权范围" min-width="240"/><el-table-column label="允许导出" width="90"><template slot-scope="{row}">{{row.allowExport?'是':'否'}}</template></el-table-column><el-table-column prop="effectiveTime" label="生效时间" min-width="160"/><el-table-column prop="expireTime" label="失效时间" min-width="160"/><el-table-column prop="status" label="状态"/></el-table></div></template><script>import{getJkHealthAuthorizationList}from'@/api/jkBusiness';export default{data(){return{query:{page:1,limit:20},list:[],loading:false}},created(){this.load()},methods:{load(){this.loading=true;getJkHealthAuthorizationList(this.query).then(r=>this.list=(r&&r.list)||(r&&r.data&&r.data.list)||r.data||r||[]).finally(()=>this.loading=false)}}}</script>